CREATE FUNCTION public.owns_ticket_event(event_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.events WHERE id=event_id AND artist=auth.uid()) $$; REVOKE EXECUTE ON FUNCTION public.owns_ticket_event(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owns_ticket_event(text) TO authenticated; ALTER POLICY own_tickets ON public.tickets USING(collector=auth.uid() OR public.owns_ticket_event(event));